func (r *MonitorResource) Update(ctx context.Context, req resource.UpdateRequest, resp *resource.UpdateResponse) {
	var plan MonitorModel
	resp.Diagnostics.Append(req.Plan.Get(ctx, &plan)...)
	var request MonitorModel
	resp.Diagnostics.Append(configWithPlannedUnknowns(ctx, req.Config, req.Plan, req.State.Raw, &request)...)
	var state MonitorModel
	resp.Diagnostics.Append(req.State.Get(ctx, &state)...)
	if resp.Diagnostics.HasError() {
		return
	}
	// An unset line's default travels only when it changes the stored value (the line was just
	// removed): resending an unchanged default can act on its own, e.g. unpause a group's members.
	if !plan.Call.Equal(state.Call) {
		request.Call = plan.Call
	}
	if !plan.CheckFrequency.Equal(state.CheckFrequency) {
		request.CheckFrequency = plan.CheckFrequency
	}
	if !plan.CriticalAlert.Equal(state.CriticalAlert) {
		request.CriticalAlert = plan.CriticalAlert
	}
	if !plan.Email.Equal(state.Email) {
		request.Email = plan.Email
	}
	if !plan.HttpMethod.Equal(state.HttpMethod) {
		request.HttpMethod = plan.HttpMethod
	}
	if !plan.Paused.Equal(state.Paused) {
		request.Paused = plan.Paused
	}
	if !plan.Push.Equal(state.Push) {
		request.Push = plan.Push
	}
	if !plan.Sms.Equal(state.Sms) {
		request.Sms = plan.Sms
	}
	vars := map[string]string{}
	vars["id"] = plan.Id.ValueString()
	out, err := r.client.Update(ctx, monitorBinding, vars, r.updateBody(ctx, request, plan, state))
	if err != nil {
		addAPIError(&resp.Diagnostics, "updating monitor", err, req.Plan.Raw.Type())
		return
	}
	if out == nil {
		out = map[string]interface{}{}
	}
	resp.State.Raw = stateFromPlan(req.Plan.Raw, req.State.Raw, out)
}

func (r *MonitorResource) Delete(ctx context.Context, req resource.DeleteRequest, resp *resource.DeleteResponse) {
	var state MonitorModel
	resp.Diagnostics.Append(req.State.Get(ctx, &state)...)
	if resp.Diagnostics.HasError() {
		return
	}
	vars := map[string]string{}
	vars["id"] = state.Id.ValueString()
	if err := r.client.Delete(ctx, monitorBinding, vars); err != nil {
		addAPIError(&resp.Diagnostics, "deleting monitor", err, req.State.Raw.Type())
	}
}

